static int ocp_read_word(struct r8152 *tp, u16 type, u16 index, u32 *value)
{
	u16 byen = BYTE_EN_WORD;
	u8 shift = index & 2;
	__le32 tmp;
	u32 data;
	int ret;

	index &= ~3;
	byen <<= shift;

	ret = generic_ocp_read(tp, index, sizeof(tmp), &tmp, type | byen);
	WARN_ON_ONCE(ret != sizeof(tmp));

	data = __le32_to_cpu(tmp);
	data >>= (shift * 8);
	data &= 0xffff;

	*value = (u16)data;

	return ret;
}
